const r=await Promise.all(["Voltaris Q2 operations update","Voltaris site disruption output","Voltaris plant outage"].map(q=>world.search(q)));
const ids=[...new Set(r.flatMap(x=>x.docs.map(d=>d.id)))];
const docs=await Promise.all(ids.map(i=>world.doc(i)));return docs.map(d=>d.id+": "+d.body);

